'use client';

import { useState, useEffect } from 'react';
import { useStore } from '@/lib/store';
import { FaPlus, FaSearch, FaEdit, FaBox, FaExclamationTriangle, FaTrash } from 'react-icons/fa';
import { toast } from 'react-hot-toast';

export default function InventoryPage() {
    const { products, addProduct, updateProduct, deleteProduct } = useStore();
    const [isClient, setIsClient] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [showModal, setShowModal] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);

    // Form State
    const [formData, setFormData] = useState({
        name: '',
        description: '',
        hsn_code: '',
        price: '',
        stock_quantity: '',
        unit: 'PCS',
        gst_rate: '18'
    });

    useEffect(() => {
        setIsClient(true);
    }, []);

    if (!isClient) return null;

    const filteredProducts = products.filter((p: any) =>
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.hsn_code?.includes(searchTerm)
    );

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        if (!formData.name || !formData.price) {
            toast.error('Name and Price are required');
            return;
        }

        const productData = {
            ...formData,
            price: parseFloat(formData.price),
            stock_quantity: parseInt(formData.stock_quantity || '0'),
            gst_rate: parseFloat(formData.gst_rate)
        };

        if (editingId) {
            updateProduct(editingId, productData);
            toast.success('Product updated');
        } else {
            addProduct({
                id: crypto.randomUUID(),
                ...productData,
                created_at: new Date().toISOString()
            });
            toast.success('Product added successfully');
        }

        resetForm();
    };

    const handleEdit = (product: any) => {
        setFormData({
            name: product.name,
            description: product.description || '',
            hsn_code: product.hsn_code || '',
            price: product.price.toString(),
            stock_quantity: product.stock_quantity.toString(),
            unit: product.unit || 'PCS',
            gst_rate: product.gst_rate?.toString() || '18'
        });
        setEditingId(product.id);
        setShowModal(true);
    };

    const resetForm = () => {
        setFormData({
            name: '', description: '', hsn_code: '', price: '', stock_quantity: '', unit: 'PCS', gst_rate: '18'
        });
        setEditingId(null);
        setShowModal(false);
    };

    const handleDelete = async (id: string) => {
        if (confirm('Are you sure you want to delete this product?')) {
            await deleteProduct(id);
        }
    };

    return (
        <div className="space-y-6 px-4 md:px-0">
            {/* Header */}
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800">Inventory</h1>
                    <p className="text-gray-500 text-sm">Manage your products and stock</p>
                </div>
                <button
                    onClick={() => setShowModal(true)}
                    className="px-5 py-2.5 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 transition shadow-lg flex items-center gap-2"
                >
                    <FaPlus /> Add New Product
                </button>
            </div>

            {/* Search */}
            <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm relative">
                <input
                    type="text"
                    placeholder="Search products by name or HSN..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full pl-4 pr-12 py-3 border border-gray-300 rounded-lg outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 transition-all"
                />
                <FaSearch className="absolute right-8 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
            </div>

            {/* List */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredProducts.length === 0 ? (
                    <div className="col-span-full py-12 text-center bg-white rounded-2xl border border-gray-100">
                        <div className="inline-block p-4 bg-gray-50 rounded-full mb-3">
                            <FaBox className="text-3xl text-gray-300" />
                        </div>
                        <p className="text-gray-500">No products found</p>
                    </div>
                ) : (
                    filteredProducts.map((product: any) => (
                        <div key={product.id} className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm hover:shadow-md transition group relative overflow-hidden">
                            {/* Low Stock Indicator */}
                            {product.stock_quantity < 10 && (
                                <div className="absolute top-0 right-0 bg-red-100 text-red-600 px-3 py-1 rounded-bl-xl text-xs font-bold flex items-center gap-1">
                                    <FaExclamationTriangle /> Low Stock
                                </div>
                            )}

                            <div className="flex justify-between items-start mb-3">
                                <div className="p-2 bg-indigo-50 rounded-lg text-indigo-600 font-bold text-lg w-10 h-10 flex items-center justify-center">
                                    {product.name.charAt(0).toUpperCase()}
                                </div>
                                <div>
                                    <button
                                        onClick={() => handleEdit(product)}
                                        className="p-2 text-indigo-600 bg-indigo-50 hover:bg-indigo-100 rounded-lg transition-all shadow-sm hover:shadow-md"
                                        title="Edit Product"
                                    >
                                        <FaEdit />
                                    </button>
                                    <button
                                        onClick={() => handleDelete(product.id)}
                                        className="p-2 text-red-600 bg-red-50 hover:bg-red-100 rounded-lg transition-all shadow-sm hover:shadow-md ml-2"
                                        title="Delete Product"
                                    >
                                        <FaTrash />
                                    </button>
                                </div>
                            </div>

                            <h3 className="font-bold text-gray-800 text-lg mb-1 truncate">{product.name}</h3>
                            <p className="text-sm text-gray-500 mb-4 line-clamp-1">{product.description || 'No description'}</p>

                            <div className="flex items-center justify-between pt-3 border-t border-gray-100">
                                <div>
                                    <p className="text-xs text-gray-400 uppercase font-semibold">Price</p>
                                    <p className="text-gray-900 font-bold">₹{product.price}</p>
                                </div>
                                <div className="text-right">
                                    <p className="text-xs text-gray-400 uppercase font-semibold">Stock</p>
                                    <p className={`font-bold ${product.stock_quantity < 10 ? 'text-red-600' : 'text-emerald-600'}`}>
                                        {product.stock_quantity} {product.unit}
                                    </p>
                                </div>
                            </div>
                        </div>
                    ))
                )}
            </div>

            {/* Add/Edit Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-2xl w-full max-w-md p-6 shadow-2xl animate-in fade-in zoom-in duration-200 overflow-y-auto max-h-[90vh]">
                        <h2 className="text-xl font-bold mb-4">{editingId ? 'Edit Product' : 'Add New Product'}</h2>
                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Product Name *</label>
                                <input
                                    required
                                    className="w-full p-2.5 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500"
                                    value={formData.name}
                                    onChange={e => setFormData({ ...formData, name: e.target.value })}
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Price (₹) *</label>
                                    <input
                                        type="number"
                                        required
                                        className="w-full p-2.5 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500"
                                        value={formData.price}
                                        onChange={e => setFormData({ ...formData, price: e.target.value })}
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">GST Rate (%)</label>
                                    <select
                                        className="w-full p-2.5 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500"
                                        value={formData.gst_rate}
                                        onChange={e => setFormData({ ...formData, gst_rate: e.target.value })}
                                    >
                                        <option value="0">0%</option>
                                        <option value="5">5%</option>
                                        <option value="12">12%</option>
                                        <option value="18">18%</option>
                                        <option value="28">28%</option>
                                    </select>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Stock Qty</label>
                                    <input
                                        type="number"
                                        className="w-full p-2.5 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500"
                                        value={formData.stock_quantity}
                                        onChange={e => setFormData({ ...formData, stock_quantity: e.target.value })}
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Unit</label>
                                    <input
                                        list="units"
                                        className="w-full p-2.5 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500 uppercase"
                                        value={formData.unit}
                                        onChange={e => setFormData({ ...formData, unit: e.target.value.toUpperCase() })}
                                        placeholder="PCS, KG, GM..."
                                    />
                                    <datalist id="units">
                                        <option value="PCS" />
                                        <option value="KG" />
                                        <option value="GM" />
                                        <option value="LTR" />
                                        <option value="ML" />
                                        <option value="BOX" />
                                        <option value="DOZEN" />
                                        <option value="PACK" />
                                    </datalist>
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">HSN Code</label>
                                <input
                                    className="w-full p-2.5 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500"
                                    value={formData.hsn_code}
                                    onChange={e => setFormData({ ...formData, hsn_code: e.target.value })}
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
                                <textarea
                                    className="w-full p-2.5 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500 h-20 resize-none"
                                    value={formData.description}
                                    onChange={e => setFormData({ ...formData, description: e.target.value })}
                                ></textarea>
                            </div>
                            <div className="flex gap-3 pt-2">
                                <button
                                    type="button"
                                    onClick={resetForm}
                                    className="flex-1 py-2.5 border border-gray-300 rounded-xl font-semibold text-gray-600 hover:bg-gray-50"
                                >
                                    Cancel
                                </button>
                                <button
                                    type="submit"
                                    className="flex-1 py-2.5 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700"
                                >
                                    {editingId ? 'Update' : 'Save Product'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useStore } from '@/lib/store';
import { useRouter } from 'next/navigation';
import { FaPlus, FaTrash, FaSave, FaArrowLeft, FaUserPlus } from 'react-icons/fa';
import Link from 'next/link';
import { toast } from 'react-hot-toast';

export default function NewInvoicePage() {
    const router = useRouter();
    const { customers, products, addInvoice, addCustomer } = useStore();
    const [isClient, setIsClient] = useState(false);

    // Form State
    const [customerId, setCustomerId] = useState('');
    const [invoiceDate, setInvoiceDate] = useState(new Date().toISOString().split('T')[0]);
    const [paidAmount, setPaidAmount] = useState('');
    const [selectedItems, setSelectedItems] = useState<any[]>([]);
    const [notes, setNotes] = useState('');

    // Modal State
    const [showCustomerModal, setShowCustomerModal] = useState(false);
    const [newCustomerName, setNewCustomerName] = useState('');
    const [newCustomerPhone, setNewCustomerPhone] = useState('');

    useEffect(() => {
        setIsClient(true);
    }, []);

    if (!isClient) return null;

    // Add Item to Invoice
    const addItem = () => {
        setSelectedItems([...selectedItems, { product_id: '', quantity: 1, unit_price: 0, gst_rate: 18 }]);
    };

    // Update Item Details
    const updateItem = (index: number, field: string, value: any) => {
        const newItems = [...selectedItems];
        if (field === 'product_id') {
            const product = products.find((p: any) => p.id === value);
            if (product) {
                newItems[index] = {
                    ...newItems[index],
                    product_id: value,
                    product_name: product.name,
                    unit_price: product.price,
                    gst_rate: product.gst_rate || 18,
                    hsn_code: product.hsn_code,
                    unit: product.unit || 'PCS'
                };
            }
        } else {
            newItems[index][field] = value;
        }
        setSelectedItems(newItems);
    };

    // Remove Item
    const removeItem = (index: number) => {
        const newItems = selectedItems.filter((_, i) => i !== index);
        setSelectedItems(newItems);
    };

    // Calculate Totals
    const calculateTotals = () => {
        return selectedItems.reduce((acc, item) => {
            const amount = item.quantity * item.unit_price;
            const gstAmount = (amount * item.gst_rate) / 100;
            return {
                subtotal: acc.subtotal + amount,
                gst: acc.gst + gstAmount,
                total: acc.total + amount + gstAmount
            };
        }, { subtotal: 0, gst: 0, total: 0 });
    };

    const totals = calculateTotals();

    // Handle Quick Customer Add
    const handleAddCustomer = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newCustomerName) return toast.error('Name is required');

        const newId = crypto.randomUUID();
        addCustomer({
            id: newId,
            name: newCustomerName,
            phone: newCustomerPhone,
            created_at: new Date().toISOString()
        });

        setCustomerId(newId);
        setShowCustomerModal(false);
        setNewCustomerName('');
        setNewCustomerPhone('');
        toast.success('Customer added & selected');
    };

    // Handle Submit
    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!customerId) {
            toast.error('Please select a customer');
            return;
        }
        if (selectedItems.length === 0) {
            toast.error('Please add at least one item');
            return;
        }


        // Validate all items have products selected
        const hasEmptyProducts = selectedItems.some(item => !item.product_id);
        if (hasEmptyProducts) {
            toast.error('Please select a product for all items');
            return;
        }

        // Check stock availability for each product
        const outOfStockItems = [];
        for (const item of selectedItems) {
            const product = products.find((p: any) => p.id === item.product_id);
            if (product) {
                const availableStock = product.stock_quantity || 0;
                if (availableStock < item.quantity) {
                    outOfStockItems.push({
                        name: item.product_name,
                        requested: item.quantity,
                        available: availableStock
                    });
                }
            }
        }

        if (outOfStockItems.length > 0) {
            const errorMessage = outOfStockItems.map(item =>
                `${item.name}: ${item.requested} requested but only ${item.available} available`
            ).join('\n');
            toast.error(`Stock not available:\n${errorMessage}`, { duration: 5000 });
            return;
        }





        const customer = customers.find((c: any) => c.id === customerId);

        // Add total_amount to each item for PDF generation
        const itemsWithTotals = selectedItems.map(item => {
            const itemSubtotal = item.quantity * item.unit_price;
            const itemGST = (itemSubtotal * item.gst_rate) / 100;
            return {
                ...item,
                total_amount: itemSubtotal + itemGST
            };
        });

        // Calculate GST breakdown using utility function
        const { calculateInvoiceTotal } = await import('@/lib/gst-calculator');
        const gstBreakdown = calculateInvoiceTotal(selectedItems, false); // false = intra-state (CGST+SGST)

        // Calculate Status
        const totalAmount = gstBreakdown.total_amount;
        const paid = parseFloat(paidAmount) || 0;
        let status = 'UNPAID';
        if (paid >= totalAmount) status = 'PAID';
        else if (paid > 0) status = 'PARTIAL';

        const newInvoice = {
            id: crypto.randomUUID(),
            invoice_number: `INV-${Math.floor(1000 + Math.random() * 9000)}`,
            customer: {
                id: customerId,
                name: customer?.name || 'Unknown',
                email: customer?.email,
                address: customer?.address,
                gstin: customer?.gstin
            },
            invoice_date: invoiceDate,
            items: itemsWithTotals,
            subtotal: gstBreakdown.subtotal,
            cgst_amount: gstBreakdown.cgst_amount,
            sgst_amount: gstBreakdown.sgst_amount,
            igst_amount: gstBreakdown.igst_amount,
            total_amount: gstBreakdown.total_amount,
            paid_amount: paid,
            payment_status: status,
            total_tax: gstBreakdown.cgst_amount + gstBreakdown.sgst_amount + gstBreakdown.igst_amount,
            status: status,
            notes: notes,
            created_at: new Date().toISOString()
        };

        // Properly await the async call
        const result = await addInvoice(newInvoice);

        // addInvoice already shows toast and navigates on success
        // Only navigate if result is successful
        if (result?.success || result?.id) {
            router.push('/dashboard/invoices');
        } else if (result?.error) {
            toast.error(`Failed: ${result.error}`);
        } else {
            toast.error('Failed to save invoice. Please try again.');
        }
    };

    return (
        <div className="max-w-5xl mx-auto space-y-6 pb-20 px-2 sm:px-4 md:px-0">
            {/* Header */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                <div className="flex items-center gap-3">
                    <Link href="/dashboard/invoices" className="p-2.5 hover:bg-indigo-50 rounded-xl transition-all border border-transparent hover:border-indigo-200">
                        <FaArrowLeft className="text-indigo-600" size={18} />
                    </Link>
                    <div>
                        <h1 className="text-2xl md:text-3xl font-bold bg-gradient-to-r from-indigo-600 to-purple-600 bg-clip-text text-transparent">New Invoice</h1>
                        <p className="text-xs sm:text-sm text-slate-600 mt-0.5">Create a professional invoice for your customer</p>
                    </div>
                </div>
            </div>

            <div className="bg-white rounded-2xl shadow-lg border border-slate-200 p-6 sm:p-8 md:p-10 space-y-6 md:space-y-8">
                {/* Customer & Dates */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    <div className="space-y-4">
                        <label className="text-sm font-bold text-gray-700 flex justify-between uppercase tracking-wider text-xs">
                            Customer
                            <button
                                onClick={() => setShowCustomerModal(true)}
                                className="text-blue-600 text-xs font-bold hover:underline flex items-center gap-1"
                            >
                                <FaPlus size={10} /> Quick Add
                            </button>
                        </label>
                        <div className="relative">
                            <select
                                value={customerId}
                                onChange={(e) => setCustomerId(e.target.value)}
                                className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none appearance-none font-medium text-gray-700 transition-all hover:bg-white hover:border-gray-300"
                            >
                                <option value="">Select Customer</option>
                                {customers.map((c: any) => (
                                    <option key={c.id} value={c.id}>{c.name}</option>
                                ))}
                            </select>
                            <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-gray-500">
                                <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z" /></svg>
                            </div>
                        </div>
                    </div>
                    <div className="space-y-4">
                        <label className="text-sm font-bold text-gray-700 uppercase tracking-wider text-xs">Invoice Date</label>
                        <input
                            type="date"
                            value={invoiceDate}
                            onChange={(e) => setInvoiceDate(e.target.value)}
                            className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none font-medium text-gray-700 transition-all hover:bg-white hover:border-gray-300"
                        />
                    </div>
                    <div className="space-y-4">
                        <label className="text-sm font-bold text-gray-700 uppercase tracking-wider text-xs">Paid Amount (₹)</label>
                        <input
                            type="number"
                            min="0"
                            step="0.01"
                            value={paidAmount}
                            onChange={(e) => setPaidAmount(e.target.value)}
                            className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none font-medium text-gray-700 transition-all hover:bg-white hover:border-gray-300"
                        />
                        <div className="text-xs font-semibold text-right">
                            {paidAmount ? (
                                <span className={totals.total - parseFloat(paidAmount) > 0 ? 'text-red-500' : 'text-green-600'}>
                                    Due Amount: ₹{Math.max(0, totals.total - parseFloat(paidAmount)).toFixed(2)}
                                </span>
                            ) : (
                                <span className="text-slate-400">Enter amount if partial payment received</span>
                            )}
                        </div>
                    </div>
                </div>

                <hr className="border-gray-100" />

                {/* Items Section */}
                <div className="space-y-4">
                    <div className="flex items-center justify-between">
                        <h2 className="text-lg font-bold text-slate-800">Invoice Items</h2>
                        <span className="text-xs text-slate-500 bg-slate-100 px-3 py-1 rounded-full font-semibold">{selectedItems.length} {selectedItems.length === 1 ? 'Item' : 'Items'}</span>
                    </div>

                    <div className="overflow-x-auto -mx-4 sm:-mx-6 md:mx-0">
                        <div className="inline-block min-w-full align-middle">
                            <div className="overflow-hidden border border-slate-200 rounded-xl">
                                <table className="min-w-full divide-y divide-slate-200">
                                    <thead className="bg-gradient-to-r from-slate-50 to-slate-100">
                                        <tr>
                                            <th className="px-4 py-3.5 text-left text-xs font-bold text-slate-700 uppercase tracking-wider">Product</th>
                                            <th className="px-4 py-3.5 text-center text-xs font-bold text-slate-700 uppercase tracking-wider">Quantity</th>
                                            <th className="px-4 py-3.5 text-left text-xs font-bold text-slate-700 uppercase tracking-wider">Price</th>
                                            <th className="px-4 py-3.5 text-right text-xs font-bold text-slate-700 uppercase tracking-wider">Total</th>
                                            <th className="px-4 py-3.5 text-center text-xs font-bold text-slate-700 uppercase tracking-wider">Action</th>
                                        </tr>
                                    </thead>
                                    <tbody className="bg-white divide-y divide-slate-100">
                                        {selectedItems.length === 0 ? (
                                            <tr>
                                                <td colSpan={5} className="px-4 py-12 text-center">
                                                    <div className="flex flex-col items-center gap-3">
                                                        <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center">
                                                            <FaPlus className="text-slate-400 text-2xl" />
                                                        </div>
                                                        <p className="text-slate-500 font-medium">No items added yet</p>
                                                        <p className="text-xs text-slate-400">Click &quot;Add Item&quot; below to get started</p>
                                                    </div>
                                                </td>
                                            </tr>
                                        ) : selectedItems.map((item, index) => (
                                            <tr key={index} className="hover:bg-slate-50/50 transition-colors group">
                                                <td className="px-4 py-3">
                                                    <select
                                                        value={item.product_id}
                                                        onChange={(e) => updateItem(index, 'product_id', e.target.value)}
                                                        className="w-full px-3 py-2.5 border border-slate-300 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 bg-white transition-all font-medium text-slate-700"
                                                    >
                                                        <option value="">Select Product</option>
                                                        {products.map((p: any) => (
                                                            <option key={p.id} value={p.id}>{p.name}</option>
                                                        ))}
                                                    </select>
                                                </td>
                                                <td className="px-4 py-3">
                                                    <div className="flex items-center justify-center gap-2">
                                                        <input
                                                            type="number"
                                                            min="1"
                                                            value={item.quantity}
                                                            onChange={(e) => updateItem(index, 'quantity', parseInt(e.target.value))}
                                                            className="w-20 px-3 py-2.5 border border-slate-300 rounded-lg text-sm text-center outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 bg-white transition-all font-semibold text-slate-700"
                                                        />
                                                        <span className="text-xs font-semibold text-slate-500 uppercase">{item.unit || 'PCS'}</span>
                                                    </div>
                                                </td>
                                                <td className="px-4 py-3">
                                                    <div className="flex items-center gap-2">
                                                        <span className="text-slate-600 text-sm font-bold">₹</span>
                                                        <input
                                                            type="number"
                                                            value={item.unit_price}
                                                            onChange={(e) => updateItem(index, 'unit_price', parseFloat(e.target.value))}
                                                            className="flex-1 px-3 py-2.5 border border-slate-300 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 bg-white transition-all font-medium text-slate-700"
                                                        />
                                                    </div>
                                                </td>
                                                <td className="px-4 py-3 text-right text-sm font-bold text-slate-800">
                                                    ₹{(item.quantity * item.unit_price).toFixed(2)}
                                                </td>
                                                <td className="px-4 py-3 text-center">
                                                    <button
                                                        onClick={() => removeItem(index)}
                                                        className="inline-flex items-center justify-center w-8 h-8 text-red-500 hover:text-white hover:bg-red-500 rounded-lg transition-all"
                                                        title="Delete Item"
                                                    >
                                                        <FaTrash size={14} />
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>

                    <div className="flex justify-center pt-3">
                        <button
                            type="button"
                            onClick={addItem}
                            className="px-8 py-3 bg-gradient-to-r from-indigo-600 via-purple-600 to-pink-600 text-white font-bold rounded-xl hover:from-indigo-700 hover:via-purple-700 hover:to-pink-700 transition-all duration-300 shadow-lg hover:shadow-xl shadow-purple-500/30 hover:shadow-purple-500/50 flex items-center gap-2.5 text-sm transform hover:scale-105 active:scale-95"
                        >
                            <FaPlus className="text-base" /> Add Item
                        </button>
                    </div>
                </div>

                {/* Summary Section */}
                <div className="flex justify-end pt-4 border-t border-gray-100">
                    <div className="w-full md:w-1/2 lg:w-1/3 space-y-3">
                        <div className="flex justify-between text-sm text-gray-600">
                            <span>Subtotal</span>
                            <span className="font-medium">₹{totals.subtotal.toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-sm text-gray-600">
                            <span>GST Total</span>
                            <span className="font-medium">₹{totals.gst.toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between font-bold text-xl text-gray-800 pt-2 border-t border-gray-100">
                            <span>Total Amount</span>
                            <span>₹{totals.total.toFixed(2)}</span>
                        </div>
                    </div>
                </div>

                {/* Notes */}
                <div>
                    <label className="text-sm font-bold text-gray-700 block mb-2">Notes (Optional)</label>
                    <textarea
                        value={notes}
                        onChange={(e) => setNotes(e.target.value)}
                        placeholder="Payment terms, bank details, or thank you notes..."
                        className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none h-24 resize-none transition-all"
                    ></textarea>
                </div>

                {/* Bottom Action Bar */}
                <div className="flex items-center justify-end pt-6 border-t border-slate-200 mt-8 sticky bottom-0 bg-white py-4 -mx-4 sm:-mx-6 md:-mx-8 px-4 sm:px-6 md:px-8 shadow-lg md:shadow-none md:static md:border-0 md:pt-6">
                    <div className="flex gap-3 w-full sm:w-auto">
                        <button
                            type="button"
                            onClick={() => router.back()}
                            className="flex-1 sm:flex-none px-6 py-3 border-2 border-slate-300 text-slate-700 font-bold rounded-xl hover:bg-slate-50 transition-all"
                        >
                            Cancel
                        </button>
                        <button
                            onClick={handleSubmit}
                            className="flex-1 sm:flex-none px-8 py-3 bg-gradient-to-r from-indigo-600 to-purple-600 text-white font-bold rounded-xl hover:from-indigo-700 hover:to-purple-700 transition-all shadow-xl hover:shadow-2xl flex items-center justify-center gap-2 transform active:scale-95"
                        >
                            <FaSave /> Save Invoice
                        </button>
                    </div>
                </div>
            </div>

            {/* Quick Add Customer Modal */}
            {showCustomerModal && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-2xl w-full max-w-sm p-6 shadow-2xl animate-in zoom-in-95 duration-200">
                        <h3 className="text-lg font-bold mb-4">Quick Add Customer</h3>
                        <form onSubmit={handleAddCustomer} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Name *</label>
                                <input
                                    autoFocus
                                    required
                                    className="w-full p-2.5 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                                    value={newCustomerName}
                                    onChange={e => setNewCustomerName(e.target.value)}
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
                                <input
                                    className="w-full p-2.5 border border-gray-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                                    value={newCustomerPhone}
                                    onChange={e => setNewCustomerPhone(e.target.value)}
                                />
                            </div>
                            <div className="flex gap-3 pt-2">
                                <button
                                    type="button"
                                    onClick={() => setShowCustomerModal(false)}
                                    className="flex-1 py-2 border border-gray-300 rounded-lg font-semibold text-gray-600 hover:bg-gray-50"
                                >
                                    Cancel
                                </button>
                                <button
                                    type="submit"
                                    className="flex-1 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700"
                                >
                                    Save
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );

}

